const DEFAULT_CURSOR_API_URL = "https://api.cursor.com";
export async function hostedControlPlaneFetch(options, method, path, body) {
    const fetchImpl = options.fetch ?? globalThis.fetch;
    const headers = {
        Authorization: `Bearer ${resolveApiKey(options)}`,
    };
    if (body !== undefined) {
        headers["Content-Type"] = "application/json";
    }
    const init = { method, headers };
    if (body !== undefined) {
        init.body = JSON.stringify(body);
    }
    return fetchImpl(`${resolveBaseUrl(options)}${path}`, init);
}
function resolveApiKey(options) {
    const key = (options.apiKey ?? process.env.CURSOR_API_KEY)?.trim();
    if (key === undefined || key === "") {
        throw new Error("hosted control plane requires CURSOR_API_KEY (deployment pod credential on Cursor hosting)");
    }
    return key;
}
function resolveBaseUrl(options) {
    const raw = (options.baseUrl ?? process.env.CURSOR_API_BASE_URL ?? DEFAULT_CURSOR_API_URL).trim();
    return raw.endsWith("/") ? raw.slice(0, -1) : raw;
}
